            await waitForSpyCall(unlabelRequestSpy);

            expectLabels(getItems, {
                [conversation1.ID as string]: {
                    [label1.Name]: true,
                    [label2.Name]: false,
                    [label3.Name]: true,
                    [label4.Name]: false,
